import 'package:hive/hive.dart';part 'poll.g.dart';@HiveType(typeId: 20)class Poll extends HiveObject {  @HiveField(0)  final String id;  @HiveField(1)  final String question;  @HiveField(2)  final List<PollOption> options;  @HiveField(3)  final String creatorId;  @HiveField(4)  final DateTime createdAt;  @HiveField(5)  final DateTime expiresAt;  @HiveField(6)  final bool isAnonymous;  @HiveField(7)  final bool allowsMultiple;  Poll({    required this.id,    required this.question,    required this.options,    required this.creatorId,    required this.createdAt,    required this.expiresAt,    this.isAnonymous = false,    this.allowsMultiple = false,  });  bool get isExpired => DateTime.now().isAfter(expiresAt);  int get totalVotes {    return options.fold(0, (sum, opt) => sum + opt.voterIds.length);  }  bool hasVoted(String userId) {    return options.any((opt) => opt.voterIds.contains(userId));  }  bool hasVotedFor(String userId, String optionId) {    final option = options.firstWhere((opt) => opt.id == optionId,        orElse: () => PollOption(id: '', text: ''));    return option.voterIds.contains(userId);  }  int getOptionVoteCount(String optionId) {    final option = options.firstWhere((opt) => opt.id == optionId,        orElse: () => PollOption(id: '', text: ''));    return option.voterIds.length;  }  double getOptionPercentage(String optionId) {    final count = getOptionVoteCount(optionId);    final total = totalVotes;    if (total == 0) return 0;    return (count / total) * 100;  }  Poll copyWith({    String? id,    String? question,    List<PollOption>? options,    String? creatorId,    DateTime? createdAt,    DateTime? expiresAt,    bool? isAnonymous,    bool? allowsMultiple,  }) {    return Poll(      id: id ?? this.id,      question: question ?? this.question,      options: options ?? this.options,      creatorId: creatorId ?? this.creatorId,      createdAt: createdAt ?? this.createdAt,      expiresAt: expiresAt ?? this.expiresAt,      isAnonymous: isAnonymous ?? this.isAnonymous,      allowsMultiple: allowsMultiple ?? this.allowsMultiple,    );  }  Map<String, dynamic> toJson() {    return {      'id': id,      'question': question,      'options': options.map((o) => o.toJson()).toList(),      'creatorId': creatorId,      'createdAt': createdAt.toIso8601String(),      'expiresAt': expiresAt.toIso8601String(),      'isAnonymous': isAnonymous,      'allowsMultiple': allowsMultiple,    };  }  factory Poll.fromJson(Map<String, dynamic> json) {    return Poll(      id: json['id'],      question: json['question'],      options:          (json['options'] as List).map((o) => PollOption.fromJson(o)).toList(),      creatorId: json['creatorId'],      createdAt: DateTime.parse(json['createdAt']),      expiresAt: DateTime.parse(json['expiresAt']),      isAnonymous: json['isAnonymous'] ?? false,      allowsMultiple: json['allowsMultiple'] ?? false,    );  }}@HiveType(typeId: 21)class PollOption {  @HiveField(0)  final String id;  @HiveField(1)  final String text;  @HiveField(2)  final List<String> voterIds;  PollOption({    required this.id,    required this.text,    List<String>? voterIds,  }) : voterIds = voterIds ?? [];  PollOption copyWith({    String? id,    String? text,    List<String>? voterIds,  }) {    return PollOption(      id: id ?? this.id,      text: text ?? this.text,      voterIds: voterIds ?? List.from(this.voterIds),    );  }  Map<String, dynamic> toJson() {    return {      'id': id,      'text': text,      'voterIds': voterIds,    };  }  factory PollOption.fromJson(Map<String, dynamic> json) {    return PollOption(      id: json['id'],      text: json['text'],      voterIds: List<String>.from(json['voterIds'] ?? []),    );  }}